    produktow: "produktów", niedostepne: "niedostępne", zmienilo: "zmieniło", zaladowalismy: "załadowaliśmy",
    akceptacje: "akceptację", dziekujemy: "dziękujemy", kolumbie: "Kolumbię", polske: "Polskę",
    gmine: "gminę", trase: "trasę", wazna: "ważna", wysylania: "wysyłania",
    uzywana: "używana", przegladarka: "przeglądarka", udostepnic: "udostępnić", prosba: "prośba",
    proba: "próba", odleglosci: "odległości", skonfigurowac: "skonfigurować", mozna: "można",
    recznie: "ręcznie", przyblizony: "przybliżony", uzupelniony: "uzupełniony", koordynatow: "koordynatów",
    pobrac: "pobrać", urzadzenie: "urządzenie", moglo: "mogło", ustalic: "ustalić",
    trwalo: "trwało", pozwol: "pozwól", uzyc: "użyć", zapalc: "zapłać",
