  function polishLegacyText(value) {
    return String(value || "").replace(/[A-Za-z]+/g, (word) => {
      const replacement = polishLegacyWords.get(word.toLowerCase());
      if (!replacement) return word;
      if (word === word.toUpperCase()) return replacement.toUpperCase();
      return /^[A-Z]/.test(word) ? replacement[0].toUpperCase() + replacement.slice(1) : replacement;
    });
  }

  rows.forEach(([key, es, pl, en]) => {
    const values = { es: spanishUiText(es), pl: key.startsWith("legacy.auto.") ? polishLegacyText(pl) : pl, en };
    languages.forEach((language) => {
      catalog[language][key] = values[language];
    });
    sourceToKey.set(normalize(es), key);
  });

  function translatePattern(source, language) {
    const clean = normalize(source);
    for (const pattern of patterns) {
      const match = clean.match(pattern.source);
      if (!match) continue;
      const renderer = pattern[language] || pattern.es;
      const rendered = typeof renderer === "function" ? renderer(...match.slice(1)) : "";
      return language === "es" ? spanishUiText(rendered) : rendered;
    }
    return "";
  }

  function looksTechnical(source) {
    return /\b(PGRST\d*|SQLSTATE|PostgREST|undefined|null|RPC|migration|stack trace)\b/i.test(String(source || ""));
  }

  function safeTechnicalMessage(language) {
    return {
      es: "No fue posible completar la operación. Inténtalo nuevamente.",
      pl: "Nie udało się wykonać operacji. Spróbuj ponownie.",
      en: "The operation could not be completed. Please try again.",
    }[language] || "No fue posible completar la operación. Inténtalo nuevamente.";
  }

  window.RC_ORDERA_OFFLINE_I18N = Object.freeze({
    catalog,
    rows,
    patterns,
    keyForSource(source) {
      return sourceToKey.get(normalize(source)) || "";
    },
    translate(source, language) {
      const key = sourceToKey.get(normalize(source));
      if (key) return catalog[language]?.[key] || catalog.es[key] || "";
      const patterned = translatePattern(source, language);
      if (patterned) return patterned;
      return looksTechnical(source) ? safeTechnicalMessage(language) : "";
    },
    polishText(value) {
      return polishLegacyText(value);
    },
    spanishText(value) {
      return spanishUiText(value);
    },
  });
